import{_ as i,o as a,c as t,a5 as o}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Task — G6 AI Features (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g6-ai-features/task.md","filePath":"mobile/features/g6-ai-features/task.md"}'),n={name:"mobile/features/g6-ai-features/task.md"};function c(r,e,l,s,d,h){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="task-—-g6-ai-features-mobile" tabindex="-1">Task — G6 AI Features (Mobile) <a class="header-anchor" href="#task-—-g6-ai-features-mobile" aria-label="Permalink to &quot;Task — G6 AI Features (Mobile)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a></p><h2 id="ai-hub" tabindex="-1">AI Hub <a class="header-anchor" href="#ai-hub" aria-label="Permalink to &quot;AI Hub&quot;">​</a></h2><ul><li>[ ] 3 card: Generate Video / Generate Image / Generate Caption + khối Credit balance (<code>GET /ai/credits</code>) luôn hiện đầu màn hình.</li></ul><h2 id="generate-video" tabindex="-1">Generate Video <a class="header-anchor" href="#generate-video" aria-label="Permalink to &quot;Generate Video&quot;">​</a></h2><ul><li>[ ] Style picker (<code>GET /video-styles</code>) → prompt textarea (10-1000 ký tự) → ambassador picker (optional, <code>/ambassadors/presets</code>) → aspect ratio 16:9/9:16 → Generate.</li><li>[ ] <code>POST /videos</code> → 202, hiện ngay &quot;Đã trừ N credit — đang xử lý&quot; (charge-upfront, không chờ job xong).</li><li>[ ] Poll <code>GET /videos/{jobId}</code> — <code>refetchInterval</code> 4s, dừng khi status không còn <code>PENDING</code>/<code>PROCESSING</code> (<code>refetchInterval: (data) =&gt; isOpen(status) ? 4000 : false</code>).</li><li>[ ] Result: <code>status=COMPLETED</code> → hiện <code>videoUrl</code> (stream signed URL trực tiếp, không proxy qua app); <code>status=FAILED</code> → hiện <code>errorCode</code> + thông báo credit đã hoàn (<code>refunded=true</code>).</li><li>[ ] Invalidate <code>[&#39;ai&#39;,&#39;credits&#39;, workspaceId]</code> ngay sau <code>POST /videos</code> thành công, và lại 1 lần nữa khi job chuyển COMPLETED/FAILED.</li><li>[ ] Không tự làm timeout logic — server sweep job treo mỗi 60s, mobile chỉ poll hoặc hỏi lại khi mở app.</li><li>[ ] Cảnh báo dùng Wifi khi preview/download video lớn (vài chục MB).</li></ul><h2 id="generate-caption" tabindex="-1">Generate Caption <a class="header-anchor" href="#generate-caption" aria-label="Permalink to &quot;Generate Caption&quot;">​</a></h2><ul><li>[ ] Form: topic textarea (10-1000 ký tự), tone/platform/length/language/goal picker, optional trend/task link.</li><li>[ ] <code>POST /captions</code> — đồng bộ, hiện spinner ngắn, trả 3 variant ngay.</li><li>[ ] Hiện mỗi variant kèm <code>signals</code> (emotion/trend_used/unverified_claims) + <code>compliance</code> check.</li><li>[ ] Nút chọn variant → <code>POST /captions/{generationId}/choice</code> (không bắt buộc MVP nhưng nên gọi để history/few-shot đúng).</li><li>[ ] Refine (<code>POST /captions/refine</code>) và Adapt platform khác (<code>POST /captions/adapt</code>) từ variant đã chọn.</li><li>[ ] Invalidate credit balance sau generate thành công.</li></ul><h2 id="generate-image" tabindex="-1">Generate Image <a class="header-anchor" href="#generate-image" aria-label="Permalink to &quot;Generate Image&quot;">​</a></h2><ul><li>[ ] Style template picker (FR 3.7.4) → form input + ambassador picker + chọn material liên quan (Material Repository, liên kết G2).</li><li>[ ] <code>POST /image/commercial/generate</code> — đồng bộ, <strong>lấy shape request/response thật từ <code>brandhub-ai-service</code>/web trước khi code</strong> (JsonNode tự do, không DTO Java).</li><li>[ ] Spinner chờ response (không có job/progress API) — <strong>cảnh báo UX nếu lâu, chưa xác nhận thời gian xử lý thật (mục 8 câu 4)</strong>.</li><li>[ ] <strong>KHÔNG hiện &quot;đã trừ N credit&quot; cho Image</strong> cho tới khi xác nhận với BE credit flow thật (mục 8 câu 3 — <code>AiGenerationController</code> không gọi <code>AiCreditService</code> ở tầng Java, có thể là gap).</li></ul><h2 id="result-preview-save" tabindex="-1">Result Preview / Save <a class="header-anchor" href="#result-preview-save" aria-label="Permalink to &quot;Result Preview / Save&quot;">​</a></h2><ul><li>[ ] Gắn kết quả vào Task (liên kết G5) hoặc lưu Material Repository (liên kết G2).</li><li>[ ] Export file về máy (FR 3.7.8).</li></ul><h2 id="credit-history" tabindex="-1">Credit History <a class="header-anchor" href="#credit-history" aria-label="Permalink to &quot;Credit History&quot;">​</a></h2><ul><li>[ ] Video job history — <code>GET /videos</code> (tối đa 12 job gần nhất).</li><li>[ ] Caption history — <strong>chặn bởi mục 8 câu 5, chưa có endpoint <code>GET</code> list caption generation, cần backend thêm trước khi làm màn này đầy đủ cho caption</strong>.</li></ul><h2 id="business-rules-can-enforce-o-client" tabindex="-1">Business rules cần enforce ở client <a class="header-anchor" href="#business-rules-can-enforce-o-client" aria-label="Permalink to &quot;Business rules cần enforce ở client&quot;">​</a></h2><ul><li>[ ] Charge trước khi generate (video) — UI nói rõ &quot;đã trừ credit&quot; ngay bước Generating, không chờ kết quả.</li><li>[ ] Bắt lỗi <code>INSUFFICIENT_AI_CREDIT</code> (402) riêng — thông báo &quot;không đủ credit&quot; + link Subscription/Billing (G7), không lỗi chung.</li><li>[ ] Phân biệt lỗi <code>INVALID_REQUEST</code> (style/ambassador sai, không trừ credit) vs <code>AI_SERVICE_UNAVAILABLE</code> (lỗi hạ tầng, cũng không trừ credit) — khác với job fail sau khi đã charge (có refund) — copy UI khác nhau cho 2 trường hợp.</li><li>[ ] Không giả lập % tiến trình không có thật — chỉ phản ánh đúng PENDING/PROCESSING/COMPLETED/FAILED.</li></ul><h2 id="chua-lam-out-of-scope-g6-xem-spec-muc-7" tabindex="-1">Chưa làm / out of scope G6 (xem spec mục 7) <a class="header-anchor" href="#chua-lam-out-of-scope-g6-xem-spec-muc-7" aria-label="Permalink to &quot;Chưa làm / out of scope G6 (xem spec mục 7)&quot;">​</a></h2><ul><li>[ ] Không làm: edit video/raw footage có sẵn (G8), quản lý Admin-level AI style/template, Trending Topics dashboard đầy đủ, Livestream Script, Recommend Collaborator.</li></ul><h2 id="rui-ro-can-chot-truoc-khi-code-xem-spec-muc-8" tabindex="-1">Rủi ro cần chốt trước khi code (xem spec mục 8) <a class="header-anchor" href="#rui-ro-can-chot-truoc-khi-code-xem-spec-muc-8" aria-label="Permalink to &quot;Rủi ro cần chốt trước khi code (xem spec mục 8)&quot;">​</a></h2><ol><li>Push notification khi job video xong — server chưa có cơ chế push (FCM/APNs/Expo), cần task riêng ở backend trước khi mobile tận dụng; nếu không có, chỉ polling khi app foreground.</li><li>Download/preview video lớn trên mobile data — cảnh báo Wifi, dùng signed URL stream trực tiếp.</li><li>Credit flow Image generation chưa rõ — xác nhận với BE ai-service Python có tự trừ credit hay là gap thật.</li><li>Image generation không có job/status polling — nếu xử lý lâu, cần bàn đổi sang pattern async/job trước khi mobile cam kết UX đồng bộ.</li><li>Danh sách lịch sử Caption generation — cần thêm endpoint <code>GET /captions</code> list ở backend (tương tự <code>GET /videos</code>) nếu muốn History đầy đủ cả 2 loại.</li></ol>',20)])])}const p=i(n,[["render",c]]);export{g as __pageData,p as default};
